extends SceneTree

const NO_KEY: int = 0x7FFFFFFFFFFFFFFF

class KeyBuf extends RefCounted:
	var buf := PackedInt64Array()
	var count: int = 0
	var is_all: bool = false
	var cap: int
	func _init(c: int) -> void:
		cap = c
		buf.resize(c)
		buf.fill(NO_KEY)
	func mark(key: int) -> void:
		if is_all:
			return
		if buf.has(key):
			return
		if count == cap:
			is_all = true
			count = 0
			return
		buf[count] = key
		count += 1
	func clear() -> void:
		buf.fill(NO_KEY)
		count = 0
		is_all = false

class Sub extends RefCounted:
	var hits: int = 0
	func on_batch(a: int) -> int:
		hits += a
		return hits

class Em extends RefCounted:
	signal changed(a: int)

func bench_marks(distinct: int, marks: int, cap: int) -> void:
	var kb := KeyBuf.new(cap)
	var t0 := Time.get_ticks_usec()
	var ticks := 1000
	for t in ticks:
		for i in marks:
			kb.mark((1 << 32) | (i % distinct))
		kb.buf.sort() if kb.count > 0 else null
		kb.clear()
	var dt := Time.get_ticks_usec() - t0
	print("MARK cap=", cap, " distinct=", distinct, " marks/tick=", marks, " -> ", float(dt) / ticks, " us/tick (", float(dt) / (ticks * marks) * 1000.0, " ns/mark incl. sort+clear)")

func _init() -> void:
	bench_marks(38, 38, 256)
	bench_marks(38, 200, 256)
	bench_marks(256, 256, 256)
	bench_marks(1, 1, 256)
	# overflow -> ALL
	var kb := KeyBuf.new(256)
	for i in 257:
		kb.mark((1 << 32) | i)
	print("OVERFLOW is_all=", kb.is_all, " count=", kb.count)
	var kb2 := KeyBuf.new(256)
	for i in 256:
		kb2.mark((1 << 32) | i)
	print("EXACT256 is_all=", kb2.is_all, " count=", kb2.count)
	var objs0 := Performance.get_monitor(Performance.OBJECT_COUNT)
	for i in 5000:
		kb2.clear()
		for j in 100:
			kb2.mark((2 << 32) | j)
	print("OBJECT_COUNT delta over 5000 cycles=", Performance.get_monitor(Performance.OBJECT_COUNT) - objs0)

	# dispatch: Callable.call vs signal emit, 10 subscribers
	var subs: Array[Sub] = []
	var calls: Array[Callable] = []
	var em := Em.new()
	for i in 10:
		var s := Sub.new()
		subs.append(s)
		calls.append(Callable(s, "on_batch"))
		em.changed.connect(s.on_batch)
	var N := 20000
	var t0 := Time.get_ticks_usec()
	for n in N:
		for c in calls:
			if c.is_valid():
				c.call(1)
	var dt_call := Time.get_ticks_usec() - t0
	t0 = Time.get_ticks_usec()
	for n in N:
		em.changed.emit(1)
	var dt_sig := Time.get_ticks_usec() - t0
	print("DISPATCH 10 subs: Callable.call loop with is_valid ", float(dt_call) / (N * 10) * 1000.0, " ns/call ; signal emit ", float(dt_sig) / (N * 10) * 1000.0, " ns/call")
	quit()
EOF
