extends SceneTree
class H extends RefCounted:
	func m(x: int) -> int:
		return x
	func lam() -> Callable:
		return func(x: int) -> int: return x
func _init() -> void:
	var h := H.new()
	var c := Callable(h, "m")
	var b := c.bind(1)
	var l: Callable = h.lam()
	print("method: custom=", c.is_custom(), " standard=", c.is_standard(), " name=", c.get_method(), " argc=", c.get_argument_count())
	print("bound : custom=", b.is_custom(), " standard=", b.is_standard(), " name=", b.get_method(), " obj_ok=", b.get_object() == h)
	print("lambda: custom=", l.is_custom(), " standard=", l.is_standard(), " name='", l.get_method(), "' obj=", l.get_object())
	print("lambda hash/eq with same? ", l == h.lam())
	quit()
EOF
